function findValidSplit(nums) {
  const last = new Map();
  const factors = [];

  for (let i = 0; i < nums.length; i++) {
    const primes = [];
    let value = nums[i];
    for (let p = 2; p * p <= value; p++) {
      if (value % p === 0) {
        primes.push(p);
        while (value % p === 0) {
          value /= p;
        }
      }
    }
    if (value > 1) {
      primes.push(value);
    }
    for (const prime of primes) {
      last.set(prime, i);
    }
    factors.push(primes);
  }

  let reach = 0;
  for (let i = 0; i < nums.length - 1; i++) {
    for (const prime of factors[i]) {
      reach = Math.max(reach, last.get(prime));
    }
    if (reach <= i) {
      return i;
    }
  }
  return -1;
}

