    return [Array.from({ length: n }, () => pick(pool))];
  }
  const n = 2000;
  if (rand() < 0.2) {
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000000))];
  }
  const primes = [];
  for (let p = 2; primes.length < 300; p++) {
    let prime = true;
    for (let d = 2; d * d <= p; d++) if (p % d === 0) { prime = false; break; }
    if (prime) primes.push(p);
  }
  primes.push(999983, 999979, 999961);
  const blocks = 2 + Math.floor(rand() * 6);
  const owner = new Map(primes.map(p => [p, Math.floor(rand() * blocks)]));
  const byBlock = Array.from({ length: blocks }, (_, b) => primes.filter(p => owner.get(p) === b));
  const nums = [];
  for (let i = 0; i < n; i++) {
    const block = Math.min(blocks - 1, Math.floor(i * blocks / n));
    const list = byBlock[block].length ? byBlock[block] : [1];
    let value = 1;
    const count = rand() < 0.1 ? 0 : 1 + Math.floor(rand() * 3);
    for (let k = 0; k < count; k++) {
      const p = pick(list);
      if (value * p <= 1000000) value *= p;
    }
    nums.push(value);
  }
  return [nums];
}
